// Strategy Config - edit these values. Everything downstream reads from here.
return [{
  json: {
    symbol: 'BTCUSDT',
    // api.binance.com is geo-blocked in some regions; the public market-data mirror is not.
    marketDataUrl: 'https://data-api.binance.vision/api/v3/klines',

    // Paper account (no real orders are ever placed by this workflow)
    startingEquity: 10000,
    riskPerTradePct: 0.5,        // % of equity risked per trade (his stated rule was 1%)
    minRewardRisk: 3,            // he rejects anything under 3:1
    maxLeverage: 5,              // cap; his 20-100x is deliberately not copied
    maxLossesPerDay: 2,          // stop for the day after 2 losing trades
    lossStreakDownsize: 8,       // after N consecutive losses, risk is divided by 3 (his "downsize 3x" rule)
    moveStopToBreakevenAtR: 0,   // 0 = off. Backtest: moving to break-even at +1R cut expectancy on every timeframe

    // Which setups the Signal Engine may propose. Defaults follow backtest/RESULTS.md:
    // only the 4h "Model" was positive after costs; 15m/1h lost money in every variant.
    executionTimeframes: ['4h'],
    enabledSetups: ['model_21_200'],   // also available: 'sma200_reclaim' (no edge in backtest), 'daily_body_reversal' (untested)
    maxSignalAgeMinutes: 60,           // ignore signals from candles that closed longer ago than this

    // Filters (backtest on 4h: stoch timing helped; regime, HTF and calendar filters lowered expectancy)
    requireStochTiming: true,      // Stoch RSI below 30 in the last 3 bars and turning up (mirror for shorts)
    requireRegimeAlignment: false, // longs only above the daily 200 SMA, shorts only below
    requireHtfAlignment: false,    // next-higher timeframe must be on the same side of its 200 SMA
    calendarBlackout: false,       // his rule: no entries Sat, Sun, Mon before 18:00 ET, Fri after 12:00 ET
    // Add scheduled high-impact events (FOMC, CPI) as ISO dates; entries are blocked that day.
    eventBlackoutDates: [],

    telegramChatId: 'REPLACE_WITH_CHAT_ID'
  }
}];

// Signal Engine: fetches closed candles, computes the indicators Crypto Lifer uses
// (21/50/200 SMA, Stoch RSI 14/14/3/3, RSI 14, ATR 14) and detects his setups
// deterministically. The agents only judge these candidates; they never invent levels.
const cfg = $input.first().json;
const TIMEFRAMES = ['15m', '1h', '4h', '1d', '3d', '1w'];
const TF_MS = { '15m': 9e5, '1h': 36e5, '4h': 144e5, '1d': 864e5, '3d': 2592e5, '1w': 6048e5 };
const NEXT_TF = { '15m': '1h', '1h': '4h', '4h': '1d', '1d': '3d', '3d': '1w' };

async function fetchClosedBars(interval) {
  const raw = await this.helpers.httpRequest({
    method: 'GET',
    url: cfg.marketDataUrl,
    qs: { symbol: cfg.symbol, interval, limit: 1000 },
    json: true,
  });
  const now = Date.now();
  return raw
    .filter((k) => Number(k[6]) < now) // drop the still-forming candle
    .map((k) => ({ t: Number(k[0]), o: +k[1], h: +k[2], l: +k[3], c: +k[4], v: +k[5] }));
}

function sma(values, n) {
  const out = new Array(values.length).fill(null);
  let sum = 0;
  for (let i = 0; i < values.length; i++) {
    sum += values[i];
    if (i >= n) sum -= values[i - n];
    if (i >= n - 1) out[i] = sum / n;
  }
  return out;
}

function rsi(closes, n = 14) {
  const out = new Array(closes.length).fill(null);
  let gain = 0, loss = 0;
  for (let i = 1; i < closes.length; i++) {
    const d = closes[i] - closes[i - 1];
    const g = Math.max(d, 0), l = Math.max(-d, 0);
    if (i <= n) {
      gain += g / n; loss += l / n;
      if (i === n) out[i] = loss === 0 ? 100 : 100 - 100 / (1 + gain / loss);
    } else {
      gain = (gain * (n - 1) + g) / n; loss = (loss * (n - 1) + l) / n;
      out[i] = loss === 0 ? 100 : 100 - 100 / (1 + gain / loss);
    }
  }
  return out;
}

function stochRsi(closes) {
  const r = rsi(closes, 14);
  const raw = r.map((v, i) => {
    const win = i < 27 || v === null ? [] : r.slice(i - 13, i + 1);
    const lo = Math.min(...win), hi = Math.max(...win);
    const value = hi === lo ? 0 : ((v - lo) / (hi - lo)) * 100;
    return win.length ? value : null;
  });
  const smooth = (arr, n) => arr.map((_, i) => {
    const win = arr.slice(Math.max(0, i - n + 1), i + 1);
    return win.length < n || win.some((x) => x === null) ? null : win.reduce((a, b) => a + b, 0) / n;
  });
  const k = smooth(raw, 3);
  return { rsi: r, k, d: smooth(k, 3) };
}

function atr(bars, n = 14) {
  const out = new Array(bars.length).fill(null);
  let prev = null;
  for (let i = 1; i < bars.length; i++) {
    const tr = Math.max(bars[i].h - bars[i].l, Math.abs(bars[i].h - bars[i - 1].c), Math.abs(bars[i].l - bars[i - 1].c));
    prev = prev === null ? tr : (prev * (n - 1) + tr) / n;
    if (i >= n) out[i] = prev;
  }
  return out;
}

const round = (x, d = 2) => (x === null || x === undefined ? null : Math.round(x * 10 ** d) / 10 ** d);

function analyse(tf, bars) {
  const closes = bars.map((b) => b.c);
  const s21 = sma(closes, 21), s50 = sma(closes, 50), s200 = sma(closes, 200);
  const st = stochRsi(closes), a = atr(bars);
  const i = bars.length - 1, b = bars[i];
  const kRecent = st.k.slice(i - 2, i + 1);
  const last10 = bars.slice(i - 9, i + 1);
  return {
    tf, i, bars, s21, s200, atrArr: a,
    snapshot: {
      timeframe: tf,
      closeTime: new Date(b.t).toISOString(),
      close: b.c,
      sma21: round(s21[i]), sma50: round(s50[i]), sma200: round(s200[i]),
      aboveSma200: s200[i] !== null ? b.c > s200[i] : null,
      sma200Rising: s200[i] !== null && s200[i - 10] !== null ? s200[i] > s200[i - 10] : null,
      rsi14: round(st.rsi[i], 1),
      stochK: round(st.k[i], 1), stochD: round(st.d[i], 1),
      stochState: st.k[i] === null ? null : st.k[i] < 20 ? 'low' : st.k[i] > 80 ? 'high' : 'mid',
      stochTurningUp: st.k[i] > st.d[i] && Math.min(...kRecent) < 30,
      stochTurningDown: st.k[i] < st.d[i] && Math.max(...kRecent) > 70,
      atr14: round(a[i]),
      // Distance from the 21 in ATRs: he takes profit when price is "far from the 21"
      stretchFrom21Atr: a[i] ? round((b.c - s21[i]) / a[i], 2) : null,
      // "Tight MAs": 21 close to the 200
      sma21To200GapAtr: a[i] && s200[i] ? round((s21[i] - s200[i]) / a[i], 2) : null,
      consolidating: a[i] ? Math.max(...last10.map((x) => x.h)) - Math.min(...last10.map((x) => x.l)) < 2.5 * a[i] : null,
    },
  };
}

const series = {};
for (const tf of TIMEFRAMES) series[tf] = analyse(tf, await fetchClosedBars.call(this, tf));
const snap = Object.fromEntries(TIMEFRAMES.map((tf) => [tf, series[tf].snapshot]));
const price = series['15m'].snapshot.close;

// Higher-timeframe regime: weekly and daily close vs their 200 SMA
const dailyBull = snap['1d'].aboveSma200, weeklyBull = snap['1w'].aboveSma200;
const regime = dailyBull && weeklyBull ? 'bull' : !dailyBull && !weeklyBull ? 'bear' : 'transition';

// "200 ladder": the 200 SMAs of each timeframe act as the next magnets / targets
const ladder = TIMEFRAMES.filter((tf) => snap[tf].sma200 !== null).map((tf) => ({ tf, sma200: snap[tf].sma200 }));
const ladderAbove = ladder.filter((x) => x.sma200 > price).sort((a, b) => a.sma200 - b.sma200);
const ladderBelow = ladder.filter((x) => x.sma200 < price).sort((a, b) => b.sma200 - a.sma200);

// Calendar rules he states repeatedly (US Eastern time)
const nowEt = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/New_York' }));
const dow = nowEt.getDay(), hour = nowEt.getHours();
const isoDate = new Date().toISOString().slice(0, 10);
const calendarReasons = [];
if (dow === 6 || dow === 0) calendarReasons.push('weekend (low liquidity, stop hunts)');
if (dow === 1 && hour < 18) calendarReasons.push('"false move Monday" before 18:00 ET');
if (dow === 5 && hour >= 12) calendarReasons.push('Friday afternoon');
const eventDay = (cfg.eventBlackoutDates || []).includes(isoDate);

// Signals come from the last closed candle of the setup timeframe; execution is at the latest price.
function buildCandidate(setup, tf, direction, signalBar, stop, extra = {}) {
  const entry = price;
  const risk = Math.abs(entry - stop);
  if ((direction === 'long' && stop >= entry) || (direction === 'short' && stop <= entry)) return;
  const sign = direction === 'long' ? 1 : -1;
  const ladderTargets = (direction === 'long' ? ladderAbove : ladderBelow)
    .map((x) => ({ label: `${x.tf} 200 SMA`, price: x.sma200, rr: round((sign * (x.sma200 - entry)) / risk, 2) }));
  const s = snap[tf], next = NEXT_TF[tf];
  const wantAbove = direction === 'long';
  return {
    id: `${setup}:${tf}:${direction}`,
    signalKey: `${setup}:${tf}:${direction}@${signalBar.t}`,
    signalAgeMinutes: Math.round((Date.now() - (signalBar.t + TF_MS[tf])) / 60000),
    setup, timeframe: tf, direction,
    entry: round(entry), stop: round(stop),
    riskPct: round((risk / entry) * 100, 3),
    targets: [{ label: '3R', price: round(entry + sign * 3 * risk), rr: 3 }, ...ladderTargets.slice(0, 3)],
    filters: {
      regimeAligned: wantAbove ? dailyBull === true : dailyBull === false,
      htfAligned: next ? snap[next].aboveSma200 === wantAbove : null,
      stochTiming: wantAbove ? s.stochTurningUp : s.stochTurningDown,
      notStretched: Math.abs(s.stretchFrom21Atr ?? 0) < 3,
      calendarClear: calendarReasons.length === 0,
    },
    ...extra,
  };
}

const candidates = [];
for (const tf of cfg.executionTimeframes) {
  const { bars, i, s21, s200, atrArr } = series[tf];
  const b = bars[i], p = bars[i - 1], a = atrArr[i];
  if (!a || s200[i] === null) continue;
  const lows10 = Math.min(...bars.slice(i - 9, i + 1).map((x) => x.l));
  const highs10 = Math.max(...bars.slice(i - 9, i + 1).map((x) => x.h));

  // Setup A, "the Model" (his 2025-2026 core): above the 200, 21 above the 200,
  // price drifts sideways/down until the 21 touches it. Short is the mirror ("inverse model").
  if (cfg.enabledSetups.includes('model_21_200')) {
    if (b.c > s200[i] && s21[i] > s200[i] && b.l <= s21[i]) {
      const stop = Math.min(s200[i], lows10) - 0.1 * a;
      if (b.c - stop >= 0.5 * a && b.c - stop <= 4 * a) candidates.push(buildCandidate('model_21_200', tf, 'long', b, stop));
    }
    if (b.c < s200[i] && s21[i] < s200[i] && b.h >= s21[i]) {
      const stop = Math.max(s200[i], highs10) + 0.1 * a;
      if (stop - b.c >= 0.5 * a && stop - b.c <= 4 * a) candidates.push(buildCandidate('model_21_200', tf, 'short', b, stop));
    }
  }

  // Setup B, 200 SMA close cross (his "go-to signal" 2024-2025, "the one indicator" on the 1h)
  if (cfg.enabledSetups.includes('sma200_reclaim')) {
    if (p.c < s200[i - 1] && b.c > s200[i]) {
      candidates.push(buildCandidate('sma200_reclaim', tf, 'long', b, Math.min(s200[i], lows10) - 0.1 * a));
    }
    if (p.c > s200[i - 1] && b.c < s200[i]) {
      candidates.push(buildCandidate('sma200_reclaim', tf, 'short', b, Math.max(s200[i], highs10) + 0.1 * a));
    }
  }
}

// Setup C, daily candle-body reversal ("green candle next to a red one" / tweezer) with stochastics at an extreme
if (cfg.enabledSetups.includes('daily_body_reversal')) {
  const { bars, i } = series['1d'];
  const b = bars[i], p = bars[i - 1], d = snap['1d'];
  if (p.c < p.o && b.c > b.o && b.c >= p.o && d.stochK !== null && d.stochK < 30) {
    candidates.push(buildCandidate('daily_body_reversal', '1d', 'long', b, Math.min(b.l, p.l) - 0.1 * d.atr14));
  }
  if (p.c > p.o && b.c < b.o && b.c <= p.o && d.stochK !== null && d.stochK > 70) {
    candidates.push(buildCandidate('daily_body_reversal', '1d', 'short', b, Math.max(b.h, p.h) + 0.1 * d.atr14));
  }
}

const valid = candidates.filter(Boolean);
const eligible = valid.filter((c) =>
  c.signalAgeMinutes <= cfg.maxSignalAgeMinutes && !eventDay &&
  (!cfg.requireStochTiming || c.filters.stochTiming) &&
  (!cfg.requireRegimeAlignment || c.filters.regimeAligned) &&
  (!cfg.requireHtfAlignment || c.filters.htfAligned !== false) &&
  (!cfg.calendarBlackout || c.filters.calendarClear));

return [{
  json: {
    config: cfg,
    asOf: new Date().toISOString(),
    symbol: cfg.symbol,
    price,
    regime: { label: regime, dailyAbove200: dailyBull, weeklyAbove200: weeklyBull, threeDayAbove200: snap['3d'].aboveSma200 },
    ladder: { above: ladderAbove, below: ladderBelow },
    calendar: { blackout: calendarReasons.length > 0, reasons: calendarReasons, eventDay, easternTime: nowEt.toISOString().slice(0, 16) },
    timeframes: snap,
    candidates: eligible,
    rejectedByFilters: valid.filter((c) => !eligible.includes(c)).map((c) => ({ id: c.id, signalAgeMinutes: c.signalAgeMinutes, filters: c.filters })),
    // Recent closed 15m bars, used by the Paper Ledger to check stops/targets
    recentBars15m: series['15m'].bars.slice(-96),
  },
}];

// Paper Ledger: keeps two paper books in workflow static data and checks them against the
// 15m bars closed since the last run.
//   desk   - trades the agent team approved (one position at a time)
//   shadow - every fresh signal the engine produced, taken mechanically at 3R
// Comparing the two shows whether the agents add anything over the plain rules.
// Static data persists only for active (production) executions.
const data = $input.first().json;
const cfg = data.config;
const COST = 0.0014; // fees + slippage, round trip, as a fraction of entry price
const store = $getWorkflowStaticData('global');
store.ledger = store.ledger || { equity: cfg.startingEquity, open: null, closed: [], lossStreak: 0, day: { date: null, losses: 0, pnlR: 0 } };
store.shadow = store.shadow || { open: [], stats: { trades: 0, wins: 0, totalR: 0 } };
store.seenSignals = store.seenSignals || [];
const L = store.ledger, shadow = store.shadow;
L.stats = L.stats || { trades: 0, wins: 0, totalR: 0 };
const today = data.asOf.slice(0, 10);
if (L.day.date !== today) L.day = { date: today, losses: 0, pnlR: 0 };

// Walk new bars; returns { exitPrice, reason, barTime } when the trade closes, else undefined.
// If stop and target are both inside one bar, the stop counts first (conservative).
function step(trade, onBreakeven) {
  const sign = trade.direction === 'long' ? 1 : -1;
  let exit;
  for (const b of data.recentBars15m.filter((x) => x.t > trade.lastCheckedBar)) {
    trade.lastCheckedBar = b.t;
    const adverse = trade.direction === 'long' ? b.l : b.h;
    const favourable = trade.direction === 'long' ? b.h : b.l;
    if (sign * (adverse - trade.stop) <= 0) {
      exit = { exitPrice: trade.stop, reason: trade.stop === trade.entry ? 'breakeven stop' : 'stop loss', barTime: b.t };
      break;
    }
    if (sign * (favourable - trade.target) >= 0) {
      exit = { exitPrice: trade.target, reason: 'target', barTime: b.t };
      break;
    }
    if (onBreakeven && cfg.moveStopToBreakevenAtR > 0 && trade.stop !== trade.entry && sign * (favourable - trade.entry) >= cfg.moveStopToBreakevenAtR * trade.riskPerUnit) {
      trade.stop = trade.entry;
      onBreakeven(trade);
    }
  }
  return exit;
}
const netR = (t, exitPrice) => Math.round((((t.direction === 'long' ? 1 : -1) * (exitPrice - t.entry) - COST * t.entry) / t.riskPerUnit) * 100) / 100;

const events = [];
if (L.open) {
  const t = L.open;
  const exit = step(t, (tr) => events.push({ type: 'stop_to_breakeven', trade: { ...tr } }));
  if (exit) {
    const r = netR(t, exit.exitPrice);
    L.equity = Math.round((L.equity + r * t.riskUsd) * 100) / 100;
    L.day.pnlR = Math.round((L.day.pnlR + r) * 100) / 100;
    if (r < 0) { L.day.losses += 1; L.lossStreak += 1; } else { L.lossStreak = 0; }
    L.stats.trades += 1;
    L.stats.wins += r > 0 ? 1 : 0;
    L.stats.totalR = Math.round((L.stats.totalR + r) * 100) / 100;
    const done = { ...t, exitPrice: exit.exitPrice, exitTime: new Date(exit.barTime).toISOString(), reason: exit.reason, netR: r };
    L.closed = [done, ...L.closed].slice(0, 50);
    L.open = null;
    events.push({ type: 'closed', reason: exit.reason, trade: done, equity: L.equity });
  } else {
    // His discretionary exit: price far from the 21 with stochastics at an extreme
    const s = data.timeframes[t.timeframe];
    const sign = t.direction === 'long' ? 1 : -1;
    if (s && sign * (s.stretchFrom21Atr ?? 0) > 3 && s.stochState === (t.direction === 'long' ? 'high' : 'low')) {
      events.push({ type: 'stretch_warning', trade: { ...t }, note: `price ${s.stretchFrom21Atr} ATR from the ${t.timeframe} 21 SMA with stochastics ${s.stochState}` });
    }
  }
}

const stillOpen = [];
for (const t of shadow.open) {
  const exit = step(t);
  if (!exit) {
    stillOpen.push(t);
    continue;
  }
  const r = netR(t, exit.exitPrice);
  shadow.stats.trades += 1;
  shadow.stats.wins += r > 0 ? 1 : 0;
  shadow.stats.totalR = Math.round((shadow.stats.totalR + r) * 100) / 100;
}
shadow.open = stillOpen;

// Each signal is reviewed once, however many runs see the same closed candle
const fresh = data.candidates.filter((c) => !store.seenSignals.includes(c.signalKey));
store.seenSignals = [...fresh.map((c) => c.signalKey), ...store.seenSignals].slice(0, 200);
const lastBar = Date.parse(data.timeframes['15m'].closeTime);
for (const c of fresh) {
  if (shadow.open.some((t) => t.id === c.id)) continue;
  shadow.open.push({ id: c.id, setup: c.setup, timeframe: c.timeframe, direction: c.direction, entry: c.entry, stop: c.stop,
    target: c.targets[0].price, riskPerUnit: Math.abs(c.entry - c.stop), lastCheckedBar: lastBar });
}

const blockedReasons = [];
if (L.open) blockedReasons.push('a paper position is already open');
if (L.day.losses >= cfg.maxLossesPerDay) blockedReasons.push(`daily loss limit reached (${L.day.losses} losses today)`);
if (fresh.length === 0) blockedReasons.push('no new eligible signals');

const expectancy = (st) => (st.trades ? Math.round((st.totalR / st.trades) * 100) / 100 : null);
return [{
  json: {
    ...data,
    candidates: fresh,
    recentBars15m: undefined,
    ledger: { equity: L.equity, open: L.open, lossStreak: L.lossStreak, today: L.day, lastClosed: L.closed.slice(0, 5) },
    comparison: {
      desk: { ...L.stats, expectancyR: expectancy(L.stats) },
      shadowRules: { ...shadow.stats, open: shadow.open.length, expectancyR: expectancy(shadow.stats) },
    },
    events,
    hasEvents: events.length > 0,
    needsReview: blockedReasons.length === 0,
    blockedReasons,
  },
}];

// Format Trade Updates: one message summarising closes, break-even moves and stretch warnings.
const { events, symbol, ledger, comparison } = $input.first().json;
const lines = events.map((e) => {
  const t = e.trade;
  let line = `Take-profit warning on ${t.direction} ${symbol}: ${e.note}`;
  if (e.type === 'closed') line = `CLOSED ${t.direction} ${symbol} (${t.setup}) at ${t.exitPrice}: ${e.reason}, ${t.netR}R. Equity ${e.equity} USD`;
  if (e.type === 'stop_to_breakeven') line = `Stop moved to break-even on ${t.direction} ${symbol} (${t.entry})`;
  return line;
});
lines.push(`Agent desk: ${comparison.desk.trades} trades, ${comparison.desk.totalR}R | Plain rules: ${comparison.shadowRules.trades} trades, ${comparison.shadowRules.totalR}R`);
lines.push(`Today: ${Math.round(ledger.today.pnlR * 100) / 100}R, ${ledger.today.losses} losses, streak ${ledger.lossStreak}. Paper only.`);
return [{ json: { text: lines.join('\n') } }];

