// Risk Gate: hard rules the agents cannot override. Levels always come from the
// Signal Engine candidate, never from model output.
const ctx = $('Paper Ledger').first().json;
const cfg = ctx.config;
const decision = $input.first().json.output;
const reasons = [];

const candidate = ctx.candidates.find((c) => c.id === decision.candidateId);
if (decision.action !== 'enter') reasons.push(`desk lead decided: ${decision.action}`);
if (!candidate) reasons.push(`unknown candidate id "${decision.candidateId}"`);

let order = null;
if (candidate) {
  const target = candidate.targets.find((t) => t.label === decision.targetLabel) || candidate.targets[0];
  const riskPerUnit = Math.abs(candidate.entry - candidate.stop);
  const rr = Math.abs(target.price - candidate.entry) / riskPerUnit;
  if (rr + 0.01 < cfg.minRewardRisk) reasons.push(`reward:risk ${rr.toFixed(2)} is below ${cfg.minRewardRisk}`);

  // Risk a fixed % of equity; divide by 3 after a losing streak
  let riskPct = cfg.riskPerTradePct;
  if (ctx.ledger.lossStreak >= cfg.lossStreakDownsize) riskPct /= 3;
  const riskUsd = (ctx.ledger.equity * riskPct) / 100;
  let qty = riskUsd / riskPerUnit;
  // Leverage cap: shrink the position rather than exceed it
  const maxNotional = ctx.ledger.equity * cfg.maxLeverage;
  if (qty * candidate.entry > maxNotional) qty = maxNotional / candidate.entry;
  const notional = qty * candidate.entry;

  order = {
    candidateId: candidate.id,
    setup: candidate.setup,
    timeframe: candidate.timeframe,
    direction: candidate.direction,
    entry: candidate.entry,
    stop: candidate.stop,
    target: Math.round(target.price * 100) / 100,
    targetLabel: target.label,
    rewardRisk: Math.round(rr * 100) / 100,
    qty: Math.round(qty * 1e6) / 1e6,
    notionalUsd: Math.round(notional),
    leverage: Math.round((notional / ctx.ledger.equity) * 100) / 100,
    riskUsd: Math.round(qty * riskPerUnit * 100) / 100,
    riskPerUnit,
  };
}

return [{ json: { approved: reasons.length === 0, reasons, order, decision } }];

// Open Paper Trade: records the approved order in the ledger and formats the alert.
const { order, decision } = $input.first().json;
const ctx = $('Paper Ledger').first().json;
const store = $getWorkflowStaticData('global');
const lastBar = Date.parse(ctx.timeframes['15m'].closeTime);

store.ledger.open = {
  ...order,
  openedAt: ctx.asOf,
  lastCheckedBar: lastBar,
  thesis: decision.summary,
};

const arrow = order.direction === 'long' ? 'LONG' : 'SHORT';
const text = [
  `PAPER ${arrow} ${ctx.symbol} (${order.setup}, ${order.timeframe})`,
  `Entry ${order.entry} | Stop ${order.stop} | Target ${order.target} (${order.targetLabel}, reward:risk ${order.rewardRisk})`,
  `Size ${order.qty} (${order.notionalUsd} USD, ${order.leverage}x) risking ${order.riskUsd} USD`,
  `Regime: ${ctx.regime.label} | Confidence: ${decision.confidence}/5`,
  `Thesis: ${decision.summary}`,
  `Skeptic: ${$('Skeptic').first().json.output.verdict} - ${$('Skeptic').first().json.output.strongestObjection}`,
  'Paper trade only. Not financial advice.',
].join('\n');

return [{ json: { text } }];
